// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 value, address caller) public {
        vm.assume(value >= 0 && value <= type(uint256).max - c.getBalance(caller));
        vm.assume(caller != address(0) && caller != address(this) && caller.code.length == 0);

        uint256 sumBefore = c.getBalance(address(this)) + c.getBalance(caller);
        uint256 sentValue = 0;

        if (caller == address(this)) {
            sentValue = value;
            c.addToBalance{value: value}();
        } else {
            vm.deal(caller, value);
            vm.prank(caller);
            sentValue = value;
            c.addToBalance{value: value}();
        }

        uint256 sumAfter = c.getBalance(address(this)) + c.getBalance(caller);

        assertTrue(sumAfter == sumBefore + sentValue);
    }
}
